// Color and Side Color Classes
export class TileColor {
  constructor(public r: number, public g: number, public b: number) {}

  static fromBytes(rgb: number[]): TileColor {
    return new TileColor(rgb[0], rgb[1], rgb[2]);
  }

  getBytes(): number[] {
    return [this.r, this.g, this.b];
  }

  static random(): TileColor {
    return new TileColor(
      Math.floor(Math.random() * 100),
      Math.floor(Math.random() * 100),
      Math.floor(Math.random() * 100)
    );
  }

  static readonly WHITE = new TileColor(0x99, 0x99, 0x99);
  static readonly RED = new TileColor(0x99, 0x00, 0x00);
  static readonly GREEN = new TileColor(0x00, 0x99, 0x00);
  static readonly BLUE = new TileColor(0x00, 0x00, 0x99);
  static readonly CYAN = new TileColor(0x00, 0x99, 0x99);
  static readonly YELLOW = new TileColor(0x99, 0x99, 0x00);
  static readonly MAGENTA = new TileColor(0x99, 0x00, 0x99);
}

export class SideColors {
  constructor(
    public side1: TileColor,
    public side2: TileColor,
    public side3: TileColor,
    public side4: TileColor,
    public side5: TileColor,
    public side6: TileColor
  ) {}

  static fromBytes(colors: number[]): SideColors {
    return new SideColors(
      new TileColor(colors[0], colors[1], colors[2]),
      new TileColor(colors[3], colors[4], colors[5]),
      new TileColor(colors[6], colors[7], colors[8]),
      new TileColor(colors[9], colors[10], colors[11]),
      new TileColor(colors[12], colors[13], colors[14]),
      new TileColor(colors[15], colors[16], colors[17])
    );
  }

  getBytes(): number[] {
    return [
      ...this.side1.getBytes(),
      ...this.side2.getBytes(),
      ...this.side3.getBytes(),
      ...this.side4.getBytes(),
      ...this.side5.getBytes(),
      ...this.side6.getBytes()
    ];
  }

  static random(): SideColors {
    return new SideColors(
      TileColor.random(),
      TileColor.random(),
      TileColor.random(),
      TileColor.random(),
      TileColor.random(),
      TileColor.random()
    );
  }
}

